"""Build results/spike13a/table.md from runs/*.pkl and eval_*.json (no simulation)."""
import os, sys, glob, json, pickle, numpy as np
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'results/spike13a'); L = []
def J(p): return json.load(open(os.path.join(R, p))) if os.path.exists(os.path.join(R, p)) else None
L.append('# spike13a tables (generated by experiments/spike13a/report13.py)\n')
c = J('gate_calib.json'); r = J('gate_ref.json')
if c: L.append('## 1. Gate calibration (zero-residual success on CAL-A, n=50, by torque-bias magnitude b in Nm)\n\n| b | ' + ' | '.join(c) + ' |\n|---|' + '---|' * len(c) + '\n| succ | ' + ' | '.join('%.2f' % v for v in c.values()) + ' |\n')
if r: L.append('Gate reference (CAL n=200, b=6): constant action c*(+1,-1,+1)*(-1) with cap 12 Nm, i.e. residual = -c*12 Nm per joint; c=0.5 cancels the bias exactly.\n\n| c | ' + ' | '.join(r) + ' |\n|---|' + '---|' * len(r) + '\n| CAL succ | ' + ' | '.join('%.3f' % v for v in r.values()) + ' |\n')
rows = []
for f in sorted(glob.glob(os.path.join(R, 'runs', '*.pkl'))):
    tag = os.path.basename(f)[:-4]; d = pickle.load(open(f, 'rb'))
    for s, v in sorted(d.items()):
        a = v['args']; hold = J(f'eval_{tag}_holdout.json'); gate = J(f'eval_{tag}_gate.json'); fresh = J(f'eval_{tag}_fresh.json')
        def ev(e): return ('%+.1f [%+.1f, %+.1f]' % tuple(100 * np.array([e['seeds'][str(s)]['diff'], *e['seeds'][str(s)]['ci']]))) if e and str(s) in e['seeds'] else ''
        rows.append((tag, s, v['kind'], '%g' % a['bias'], '%g' % a['steps'], '%g' % a['lr'], '%g' % a['cap'], '%g' % a['logstd0'], a['horizon'] if v['kind'] == 'ppo' else '-', '%g' % a['ent'], a['sepclip'], a['maskprobe'], ('%g' % a['alpha']) if v['kind'] == 'sac' else '-', '%g' % a['bc'],
                     v['init']['succ'], v['selected']['succ'], v['selected']['it'], v['selected']['res_mean'], v['train_episodes'] + v['cal_eval_episodes'], v['wall'] / 60, ev(gate), ev(hold), ev(fresh)))
hdr = '| tag | seed | algo | bias | steps | lr | cap | log-std0 | horizon | ent | sepclip | maskprobe | alpha | bc | CAL init | CAL selected | sel. iter | res mean (Nm) | episodes (train+CAL eval) | wall min | gate n=200 diff pp | holdout n=500 diff pp | fresh n=200 diff pp |\n|' + '---|' * 23 + '\n'
for title, flt in (('2. Gate runs (bias 6 Nm)', lambda x: float(x[3]) > 0), ('3. Real condition runs (sweep, confirmation)', lambda x: float(x[3]) == 0)):
    L.append(f'## {title}\n\n' + hdr + '\n'.join('| ' + ' | '.join(('%.3f' % z if isinstance(z, float) and abs(z) < 5 else ('%.1f' % z if isinstance(z, float) else str(z))) for z in x) + ' |' for x in rows if flt(x)) + '\n')
for tag in sorted(set(os.path.basename(p)[5:-5].rsplit('_', 1)[0] for p in glob.glob(os.path.join(R, 'eval_*_*.json')))):
    pass
for p in sorted(glob.glob(os.path.join(R, 'eval_*.json'))):
    e = json.load(open(p)); q = e['pooled']; L.append('- %s on %s (n=%d, bias %g): init %.1f %%, pooled over %d seed(s) RL %.1f %%, diff %+.1f pp [%+.1f, %+.1f]' % (e['tag'], e['set'], e['n'], e['bias'], 100 * e['init'], len(e['seeds']), 100 * q['succ'], 100 * q['diff'], 100 * q['ci'][0], 100 * q['ci'][1]))
open(os.path.join(R, 'table.md'), 'w').write('\n'.join(L) + '\n'); print('\n'.join(L)[:6000])
